#[test]
fn decode_record_accepts_exact_path_and_link_bounds() {
    let mut buf = [0u8; HEADER_SIZE + RECORD_SIZE];
    encode_header(1, (&mut buf[..HEADER_SIZE]).try_into().unwrap());
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[2] = 3; // symlink
        rec[0..2].copy_from_slice(&(MAX_PATH as u16).to_le_bytes());
        rec[32..34].copy_from_slice(&(MAX_LINK as u16).to_le_bytes());
        rec[40] = b'/';
        for b in &mut rec[41..40 + MAX_PATH] { *b = b'a'; }
        for b in &mut rec[40 + MAX_PATH..40 + MAX_PATH + MAX_LINK] { *b = b'b'; }
    }
    // exact MAX_PATH path and MAX_LINK link must decode (boundary inclusive)
    assert!(Index::new(&buf).is_ok());
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[32..34].copy_from_slice(&((MAX_LINK + 1) as u16).to_le_bytes());
    }
    // one past MAX_LINK must be rejected at decode time
    assert_eq!(Index::new(&buf).err(), Some(VfsError::InvalidIndex));
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[32..34].copy_from_slice(&(MAX_LINK as u16).to_le_bytes());
        rec[0..2].copy_from_slice(&0u16.to_le_bytes());
    }
    // zero-length path rejected
    assert_eq!(Index::new(&buf).err(), Some(VfsError::InvalidIndex));
}

#[test]
fn event_poll_add_rejects_zero_invalid_and_duplicate() {
    let mut poll: EventPoll<4> = EventPoll::new();
    // descriptor 0 rejected even with valid events
    assert_eq!(poll.add(0, EVENT_READ), Err(ProcessError::InvalidEvent));
    // zero events rejected even with valid descriptor
    assert_eq!(poll.add(5, 0), Err(ProcessError::InvalidEvent));
    // unsupported high bit rejected
    assert_eq!(poll.add(5, EVENT_READ | 0x80), Err(ProcessError::InvalidEvent));
    // valid single-bit and combined accepted
    poll.add(5, EVENT_READ).unwrap();
    poll.add(6, EVENT_READ | EVENT_WRITE).unwrap();
    // duplicate active descriptor rejected
    assert_eq!(poll.add(5, EVENT_WRITE), Err(ProcessError::InvalidEvent));
    // removed slot can be re-added
    poll.remove(5).unwrap();
    poll.add(5, EVENT_WRITE).unwrap();
}

#[test]
fn parse_controllers_accumulates_and_skips_empty_tokens() {
    // single controller
    assert_eq!(parse_controllers(b"+cpu"), Ok(CPU));
    // multiple controllers accumulate via OR
    assert_eq!(parse_controllers(b"+cpu +memory"), Ok(CPU | MEMORY));
    assert_eq!(parse_controllers(b"+cpu +memory +pids"), Ok(CPU | MEMORY | PIDS));
    // trailing/double spaces produce empty tokens that must be skipped, not error
    assert_eq!(parse_controllers(b"+cpu "), Ok(CPU));
    assert_eq!(parse_controllers(b"+cpu  +pids"), Ok(CPU | PIDS));
    // unknown token rejected
    assert_eq!(parse_controllers(b"+io"), Err(ViewError::PermissionDenied));
    // empty input yields zero controllers
    assert_eq!(parse_controllers(b""), Ok(0));
}
